pass:
    li   t6, HALT
    sd   x0, 0(t6)
pass_loop:
    j    pass_loop
fail:
    li   t6, HALT
    sd   gp, 0(t6)
fail_loop:
    j    fail_loop

handler:                        # return to the instruction after the trap,
    mv   s3, s2                 # or s7 bytes further on
    csrr s2, mcause
    csrr s4, mepc
    addi s5, s5, 1
    addi t6, s4, 4
    add  t6, t6, s7
    li   s7, 0
    csrw mepc, t6
    mret

    .align 3
